package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.Jsoup;
import org.jsoup.helper.DataUtil;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.DataNode;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Tag;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_clone_TriageGen1Test {
    private Element element;
    private Element textNodeElement;
    private Element dataNodeElement;

    @Before
    public void setUp() {
        element = Jsoup.parse("<div id='test' class='class1 class2'><p>Test</p></div>").select("div").first();
        textNodeElement = Jsoup.parse("<div><p>Text</p></div>").select("p").first();
        dataNodeElement = Jsoup.parse("<div data-custom='value'><p>Custom</p></div>").select("p").first();
    }

    @Test
    public void testCloneBasic() {
        Element clone = element.clone();
        assertNotNull(clone);
        assertEquals(element.tagName(), clone.tagName());
        assertEquals(element.id(), clone.id());
        assertEquals(element.className(), clone.className());
        assertNotNull(clone.parent());
    }

    @Test
    public void testCloneWithText() {
        Element clone = textNodeElement.clone();
        assertNotNull(clone);
        assertEquals(textNodeElement.tagName(), clone.tagName());
        assertEquals(textNodeElement.text(), clone.text());
    }

    @Test
    public void testCloneWithDataNode() {
        Element clone = dataNodeElement.clone();
        assertNotNull(clone);
        assertEquals(dataNodeElement.tagName(), clone.tagName());
        assertEquals(dataNodeElement.data("custom"), clone.data("custom"));
    }

    @Test
    public void testCloneWithEmptyElement() {
        Element emptyElement = Jsoup.parse("<div></div>").select("div").first();
        Element clone = emptyElement.clone();
        assertNotNull(clone);
        assertTrue(clone.isEmpty());
    }

    @Test
    public void testCloneWithNestedElements() {
        Element parentElement = Jsoup.parse("<div><p><span>Nested</span></p></div>").select("div").first();
        Element clone = parentElement.clone();
        assertNotNull(clone);
        assertEquals(parentElement.select("p").size(), clone.select("p").size());
        assertEquals(parentElement.select("span").text(), clone.select("span").text());
    }

    @Test(expected = CloneNotSupportedException.class)
    public void testCloneFailure() {
        Element unsupportedElement = Jsoup.parse("<div></div>").select("div").first();
        unsupportedElement.clone(); // Assuming clone() is implemented to throw CloneNotSupportedException
    }

    @Test
    public void testCloneWithAttributes() {
        Element clone = element.clone();
        assertNotNull(clone.attr("id"));
        assertEquals(element.attr("class"), clone.attr("class"));
    }

    @Test
    public void testCloneWithMultipleClasses() {
        Element clone = element.clone();
        assertTrue(clone.hasClass("class1"));
        assertTrue(clone.hasClass("class2"));
    }

    @Test
    public void testCloneWithSelfClosingTag() {
        Element selfClosingElement = Jsoup.parse("<img src='image.jpg' />").select("img").first();
        Element clone = selfClosingElement.clone();
        assertNotNull(clone);
        assertEquals(selfClosingElement.tagName(), clone.tagName());
        assertEquals(selfClosingElement.attr("src"), clone.attr("src"));
    }
}
